var calcScore, colors, getDiffParams, getFinalWeights, globalParams, lightBearishColor, lightBearishText, lightBullishColor, lightBullishText, log, maxScore, minScore, olog, scoreRange, trendTexts;

import {
  createLogFunctions
} from "thingy-debug";

({log, olog} = createLogFunctions("scorehelper"));

import {
  //endregion

  //###########################################################
  diffParams as defaultDiffParams,
  finalWeights as defaultFinalWeights
} from "./defaultsnapshot.js";

//###########################################################
//region Trend Range Definitions
//# Notice: minScore and maxScore are 25 on purpose
//      This is to squeeze the range for the colors a bit
maxScore = 25;

minScore = -25;

scoreRange = Math.abs(maxScore - minScore);

//###########################################################
globalParams = null;

//###########################################################
// 6 gradient to red and green + grey neutral color
colors = ["#33cc00", "#55d04b", "#79d399", "#ddd", "#eb803d", "#db591e", "#cc3300"];

trendTexts = [
  // Trend Texts for all 6 gradients
  "Super Bullish", // "#33cc00"
  "Stark Bullish", // "#55d04b"
  "Bullish", // "#79d399"
  "Neutral", // "#ddd"
  "Bearish", // "#eb803d"
  "Stark Bearish", // "#db591e"
  "Super Bearish" // "#cc3300"
];

//###########################################################
//special values for +4 / -4
lightBullishColor = "#bfdac9";

lightBullishText = "Leicht Bullish";

lightBearishColor = "#e1c1ad";

lightBearishText = "Leicht Bearish";

//endregion

//###########################################################
//region Local Functions

//###########################################################
getDiffParams = function() {
  if (globalParams != null) {
    return globalParams.diffCurves;
  } else {
    return defaultDiffParams;
  }
};

getFinalWeights = function() {
  if (globalParams != null) {
    return globalParams.finalWeights;
  } else {
    return defaultFinalWeights;
  }
};

//###########################################################
calcScore = function(infl, mrr, gdpg, cot, horizon) {
  var correctionFactor, w, weighted;
  w = getFinalWeights()[horizon];
  weighted = (w.i * infl) + (w.l * mrr) + (w.g * gdpg) + (w.c * cot);
  correctionFactor = (1.0 * w.f) / (w.i + w.l + w.g + w.c);
  return weighted * correctionFactor;
};

//endregion

