//region Exported Functions

//###########################################################
export var inflDiffScore = function(diff) {
  var b, d;
  ({b, d} = getDiffParams().infl);
  return b * diff + d * diff * diff * diff;
};

export var mrrDiffScore = function(diff) {
  var b, d;
  ({b, d} = getDiffParams().mrr);
  return b * diff + d * diff * diff * diff;
};

export var gdpgDiffScore = function(diff) {
  var b, d;
  ({b, d} = getDiffParams().gdpg);
  return b * diff + d * diff * diff * diff;
};

export var cotDiffScore = function(diff) {
  var b, d;
  ({b, d} = getDiffParams().cot);
  return b * diff + d * diff * diff * diff;
};

//###########################################################
export var stScore = function(infl, mrr, gdpg, cot) {
  return calcScore(infl, mrr, gdpg, cot, "st");
};

export var mlScore = function(infl, mrr, gdpg, cot) {
  return calcScore(infl, mrr, gdpg, cot, "ml");
};

export var ltScore = function(infl, mrr, gdpg, cot) {
  return calcScore(infl, mrr, gdpg, cot, "lt");
};

//###########################################################
export var displayableScore = function(raw) {
  var score;
  score = Math.round(raw);
  if (score > 30) {
    score = 30;
  }
  if (score < -30) {
    score = -30;
  }
  return score;
};

//###########################################################
export var getTrendForScore = function(score) {
  var color, region, regionSize, text;
  log(`getTrendForScore ${score}`);
  if (score > maxScore) {
    return {
      color: colors[0],
      text: trendTexts[0]
    };
  }
  if (score < minScore) {
    return {
      color: colors[colors.length - 1],
      text: trendTexts[trendTexts.length - 1]
    };
  }
  if (Math.round(score) === 4) {
    return {
      color: lightBullishColor,
      text: lightBullishText
    };
  }
  if (Math.round(score) === -4) {
    return {
      color: lightBearishColor,
      text: lightBearishText
    };
  }
  regionSize = 1.0 * scoreRange / colors.length;
  score = 1.0 * score - minScore; // shift lower end to 0
  region = Math.floor(score / regionSize);
  region = Math.min(region, colors.length - 1);
  region = Math.max(region, 0);
  region = colors.length - 1 - region; // lower region is higher
  log(`Resulting Region: ${region}`);
  color = colors[region];
  text = trendTexts[region];
  return {color, text};
};

//###########################################################
export var setGlobalParams = function(params) {
  log("setGlobalParams");
  globalParams = params;
};


